class Solution {
public:
    int longestCommonSubsequence(string text1, string text2) {
        // Ensure text2 is the shorter one to minimise memory
        if (text2.size() > text1.size()) swap(text1, text2);
        int n = text1.size();
        int m = text2.size();
        vector<int> prev(m + 1, 0), cur(m + 1, 0);
        for (int i = 1; i <= n; ++i) {
            cur[0] = 0;
            for (int j = 1; j <= m; ++j) {
                if (text1[i - 1] == text2[j - 1])
                    cur[j] = prev[j - 1] + 1;
                else
                    cur[j] = max(prev[j], cur[j - 1]);
            }
            swap(prev, cur);
        }
        return prev[m];
    }
};
